//! Checks the pathing ports against observations of the original `Game.dll` 1.26a
//! (`data.rs`, generated by `tools/emu/pathing_vectors.py` from Unicorn runs of the binary).
//!
//! The vectors are committed data, so these tests run with or without `GAME_DLL`; the
//! variable is only needed to regenerate `data.rs`. The digests cover every checked value:
//! `isqrt` over 115,536 inputs, and the heap state after every operation of 3000 random
//! sequences (about 241k operations, many with duplicate keys).

mod build_cases;
mod build_data;
mod cases;
mod data;
mod pyramid_data;
mod request_data;
mod search_data;

use sim::pathing::heap::{Entry, Heap};
use sim::pathing::isqrt::isqrt;

const DIGEST_INIT: u64 = 0xCBF2_9CE4_8422_2325;
const DIGEST_MUL: u64 = 0x0000_0100_0000_01B3;

/// The generator of the vector script: 64-bit LCG, `u32` takes the top 32 bits.
struct Lcg(u64);

impl Lcg {
    fn u32(&mut self) -> u32 {
        self.0 = self
            .0
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        (self.0 >> 32) as u32
    }
}

fn digest_words(mut h: u64, words: &[u32]) -> u64 {
    for &w in words {
        h = h.wrapping_mul(DIGEST_MUL).wrapping_add(u64::from(w));
    }
    h
}

#[test]
fn isqrt_matches_original_over_all_small_inputs_and_random_samples() {
    for &(n, r) in data::ISQRT_SPOT {
        assert_eq!(isqrt(n), r, "isqrt({n:#010X})");
    }
    let mut digest = DIGEST_INIT;
    for n in 0..=65_535u32 {
        digest = digest_words(digest, &[isqrt(n)]);
    }
    let mut lcg = Lcg(data::ISQRT_SEED);
    for _ in 0..data::ISQRT_RANDOM {
        digest = digest_words(digest, &[isqrt(lcg.u32())]);
    }
    assert_eq!(
        digest,
        data::ISQRT_DIGEST,
        "isqrt digest over the vector set"
    );
}

/// One heap operation as the vector script generates it.
enum Op {
    Push { key: u32, node: u32, stamp: u32 },
    Pop,
}

/// Sequence `s` of the vector script: lengths 1 to 160; key masks cycle through 2-bit,
/// 4-bit, 8-bit and full 32-bit keys (so the small masks give many duplicate keys).
fn gen_ops(s: usize) -> Vec<Op> {
    let mut rng = Lcg((s as u64 + 1).wrapping_mul(0x9E37_79B9_7F4A_7C15));
    let mask = [0x3u32, 0xF, 0xFF, 0xFFFF_FFFF][s % 4];
    let length = 1 + rng.u32() % 160;
    let mut ops = Vec::with_capacity(length as usize);
    let mut size = 0u32;
    for _ in 0..length {
        let r = rng.u32() % 100;
        if r < 60 || size == 0 {
            let key = rng.u32() & mask;
            let node = rng.u32() % 1000;
            let stamp = rng.u32();
            ops.push(Op::Push { key, node, stamp });
            size += 1;
        } else {
            ops.push(Op::Pop);
            size -= 1;
        }
    }
    ops
}

/// Words of one operation's state, in the layout the vector script hashes:
/// `[kind, popped key, popped node, popped stamp, size, slots...]`, where `kind` is 0 for a
/// push (popped words are 0) and 1 for a pop, and `size` counts the sentinel slot.
fn op_words(kind: u32, popped: Entry, heap: &Heap) -> Vec<u32> {
    let mut words = vec![kind, popped.key, popped.node, popped.stamp];
    words.push(heap.slots().len() as u32);
    for e in heap.slots() {
        words.extend_from_slice(&[e.key, e.node, e.stamp]);
    }
    words
}

#[test]
fn heap_matches_original_after_every_operation() {
    for (s, &(op_count, expected)) in data::HEAP_SEQUENCES.iter().enumerate() {
        let ops = gen_ops(s);
        assert_eq!(
            ops.len(),
            op_count as usize,
            "sequence {s}: generator drift"
        );
        let mut heap = Heap::new();
        let mut digest = DIGEST_INIT;
        for op in &ops {
            let words = match *op {
                Op::Push { key, node, stamp } => {
                    heap.push(key, node, stamp);
                    op_words(0, Entry::default(), &heap)
                }
                Op::Pop => {
                    let popped = heap.pop().expect("generator never pops an empty heap");
                    op_words(1, popped, &heap)
                }
            };
            let op_hash = digest_words(DIGEST_INIT, &words);
            digest = digest.wrapping_mul(DIGEST_MUL).wrapping_add(op_hash);
        }
        assert_eq!(
            digest, expected,
            "heap sequence {s} diverges from the original"
        );
    }
}

#[test]
fn pyramid_lookups_match_original_over_random_cases() {
    for &(seed, expected) in pyramid_data::PYRAMID_CASES {
        let got = cases::run_pyramid_case(cases::pyramid_case(seed));
        assert_eq!(
            got, expected,
            "pyramid case {seed} diverges from the original"
        );
    }
}

#[test]
fn search_matches_original_over_random_cases() {
    for &(seed, expected) in search_data::SEARCH_CASES {
        let (got, _) = cases::run_search_case(cases::search_case(seed));
        assert_eq!(
            got, expected,
            "search case {seed} diverges from the original"
        );
    }
}

#[test]
fn search_paths_match_original() {
    for &(seed, request, status, cells) in search_data::SEARCH_SPOTS {
        let (_, paths) = cases::run_search_case(cases::search_case(seed));
        let (got_status, got_cells) = &paths[request];
        assert_eq!(got_status, status, "case {seed}, request {request}");
        assert_eq!(
            got_cells.as_slice(),
            cells,
            "case {seed}, request {request}"
        );
    }
}

#[test]
fn requests_match_original_over_random_cases() {
    for &(seed, expected) in request_data::REQUEST_CASES {
        let (got, _) = cases::run_request_case(cases::request_case(seed));
        assert_eq!(
            got, expected,
            "request case {seed} diverges from the original"
        );
    }
}

#[test]
fn waypoints_match_original() {
    for &(seed, request, ret, points) in request_data::REQUEST_SPOTS {
        let (_, outs) = cases::run_request_case(cases::request_case(seed));
        let out = &outs[request];
        assert_eq!(
            u64::from(out.code),
            u64::from(ret),
            "case {seed}, request {request}"
        );
        let got: Vec<(u32, u32)> = out
            .points
            .iter()
            .map(|&(x, y)| (x.to_bits(), y.to_bits()))
            .collect();
        assert_eq!(got.as_slice(), points, "case {seed}, request {request}");
    }
}
